```
/*─────────────────────────────────────────────────────────────
 * qx.ts – fluent *query* wrapper around attribute‑store (v5)
 *─────────────────────────────────────────────────────────────*/
import {
  /* entity scopes */ getAllEntities, getEntitiesOfType,
  /* attrs / roles */ getAttr, getAttrs, getRoles,
  /* look‑ups      */ queryEntitiesByAttribute,
  queryEntitiesInRelationTo,
  queryEntitiesByRelationTo,
  getAll,
} from "@/core/ears/attribute-storage";

import { relationIndex } from "@/core/ears/relation-index";
import { EARS } from "@/core/types";
import { asArr, MaybeArr } from "@/core/utils";

/*──────── helpers ────────*/
const isEntity = (v: unknown): v is EARS.Entity =>
  Object.values(EARS.Entity).includes(v as EARS.Entity);

// memoised prefix checker – avoids re‑allocating closures
const prefixCache = new Map<EARS.Entity, (id: EARS.EntityId) => boolean>();
const hasPrefix = (t: EARS.Entity) => {
  let fn = prefixCache.get(t);
  if (!fn) {
    fn = (id: EARS.EntityId) => id.startsWith(`${t}-`);
    prefixCache.set(t, fn);
  }
  return fn;
};
const b64Encode = (n: number) => Buffer.from(String(n)).toString('base64');
const b64Decode = (s: string) => {
  try {
    const decoded = Buffer.from(s, 'base64').toString();
    const num = parseInt(decoded, 10);
    return isNaN(num) ? 0 : num;
  } catch {
    return 0;
  }
};

const liftOne = <F extends (...args: any[]) => any>(many: F) =>
  (...a: Parameters<F>) => (many as any)(...a)[0] ?? null;

/*──────── entry ────────*/
export const qx = (
  seed?:
    | EARS.EntityId
    | EARS.Entity
    | readonly EARS.Entity[]
    | readonly EARS.EntityId[],
) => {
  // always clone to keep chains isolated
  const resolveSeed = (): EARS.EntityId[] => {
    if (seed === undefined) return [...getAllEntities()];
    if (Array.isArray(seed)) {
      if ((seed as readonly unknown[]).every(isEntity)) {
        return (seed as readonly EARS.Entity[]).flatMap(t => getEntitiesOfType(t));
      }
      // Filter entity IDs to only include those that actually exist
      const allEntities = new Set(getAllEntities());
      return (seed as readonly EARS.EntityId[]).filter(id => allEntities.has(id));
    }
    if (isEntity(seed)) return [...getEntitiesOfType(seed)];
    // Check if the single entity ID actually exists
    const allEntities = getAllEntities();
    return allEntities.includes(seed as EARS.EntityId) ? [seed as EARS.EntityId] : [];
  };

  let ids: EARS.EntityId[] = resolveSeed();

  /*–––– internal util to return a fresh cursor ––––*/
  const setIds = (next: EARS.EntityId[]) => qx(next);

  const self = {
    /*─ filters ─*/
    ofType: (t: EARS.Entity) => setIds(ids.filter(hasPrefix(t))),

    inIds: (sub: readonly EARS.EntityId[]) => {
      const subSet = new Set(sub);
      return setIds(ids.filter(i => subSet.has(i)));
    },

    where: (k: EARS.AttrKind | string, v?: unknown) => {
      const kind = typeof k === "string" ? EARS.AttrKind.Custom(k) : k;
      if (v === undefined) {
        const next = ids.filter(i => getAttrs(i, kind).length);
        return setIds(next);
      }
      // Use Set for O(1) lookups instead of includes() which is O(n)
      const matchingEntities = new Set(queryEntitiesByAttribute(kind, v));
      const next = ids.filter(i => matchingEntities.has(i));
      return setIds(next);
    },

    withRole: (r: string) => setIds(ids.filter(i => getRoles(i).includes(r))),

    relatedTo: (target: EARS.EntityId) => {
      const related = new Set(queryEntitiesInRelationTo(target));
      return setIds(ids.filter(i => related.has(i)));
    },

    related: (kind: string, other: EARS.EntityId, asSrc = false) =>
      setIds(ids.filter(i => queryEntitiesByRelationTo(kind, other, asSrc).includes(i))),

    /*─ graph traversal retains isolation ─*/
    linksTo: (
      relKinds: MaybeArr<string>,
      tgtType?: MaybeArr<EARS.Entity>,
      asSrc = true,
    ) => {
      const kinds = asArr(relKinds);
      const targets = tgtType ? asArr(tgtType) : [];
      const matches = (id: EARS.EntityId) => !targets.length || targets.some(t => hasPrefix(t)(id));

      const out = new Set<EARS.EntityId>();
      for (const src of ids) for (const k of kinds) {
        queryEntitiesByRelationTo(k, src, asSrc)
          .filter(matches)
          .forEach(i => {
            if (i !== src) out.add(i);            // guard reflexive links
          });
      }
      return qx([...out]);
    },

    /*─ low‑level links array ─*/
    links: <K extends string>(
      relKinds: K | readonly K[],
      tgtType?: MaybeArr<EARS.Entity>,
      asSrc = true,
    ): Array<{ relation: K; id: EARS.EntityId }> => {
      const kinds = asArr(relKinds);
      const targets = tgtType ? asArr(tgtType) : [];
      const matches = (id: EARS.EntityId) => !targets.length || targets.some(t => hasPrefix(t)(id));

      const out: Array<{ relation: K; id: EARS.EntityId }> = [];
      for (const src of ids) for (const k of kinds)
        queryEntitiesByRelationTo(k, src, asSrc)
          .filter(matches)
          .forEach(id => out.push({ relation: k as K, id }));

      return out;
    },

    /*─ relation detail helpers ─*/
    edgeIds: (
      kinds?: string | readonly string[],
      asSrc = true,
    ): EARS.EntityId[] => {
      const ksInput = kinds ? asArr(kinds) : (Object.keys(relationIndex) as readonly string[]);
      const ks = ksInput.filter(k => relationIndex[k] !== undefined); /* ➊ validate once */
      const out = new Set<EARS.EntityId>();
      for (const i of ids) for (const k of ks) {
        const dir = relationIndex[k]!;           // safe: ks filtered above
        (asSrc ? dir.bySource[i] : dir.byTarget[i])?.forEach(r => out.add(r));
      }
      return [...out];
    },

    /*─ projections ─*/
    pick: <A extends readonly string[]>(fields: A) =>
      ids.map(i => {
        const o: Record<string, unknown> = { id: i };
        fields.forEach(k => {
          if (k === "id") return;
          o[k] = getAttr(i, EARS.AttrKind.Custom(k));
        });
        return o as { id: EARS.EntityId } & { [K in A[number]]: unknown };
      }),
    pickOne: liftOne(function <A extends readonly string[]>(f: A) {
      return self.pick(f);
    }),

    pickAll: () => {
      return ids.map(i => {
        const o: Record<string, unknown> = { id: i };
        Object.assign(o, getAll(i));
        return o as { id: EARS.EntityId } & { [K in string]: unknown };
      });
    },

    /*─ traverse + project in one call ─*/
    linksPick: <K extends string, A extends readonly string[]>(
      relKinds: K | readonly K[],
      fields: A,
      tgtType?: MaybeArr<EARS.Entity>,
    ) => {
      const manyKinds = Array.isArray(relKinds) && relKinds.length > 1;
      return self.links(relKinds, tgtType).map(({ relation, id }) => ({
        ...(manyKinds ? { relation } : {}),
        ...qx(id).pickOne(fields)!,
      }));
    },

    /*─ list shaping helpers ─*/
    orderBy: (
      field: string,
      dir: "asc" | "desc" = "asc",
    ) => {
      const kind = EARS.AttrKind.Custom(field);
      const cmp = (a: unknown, b: unknown) => {
        if (a === b) return 0;
        if (a === undefined) return 1;
        if (b === undefined) return -1;
        if (typeof a === "number" && typeof b === "number") return a - b;
        return String(a).localeCompare(String(b));
      };
      const next = [...ids].sort((aId, bId) => {
        const res = cmp(getAttr(aId, kind), getAttr(bId, kind));
        return dir === "asc" ? res : -res;
      });
      return setIds(next);
    },

    reverse: () => setIds([...ids].reverse()),

    limit: (n: number) => setIds(ids.slice(0, n)),

    /*─ paging, distinct, grouping ─*/

    page: (size: number, cursor?: string | null) => {
      const start       = cursor ? b64Decode(cursor) : 0;
      const end         = start + size;
      const sliceIds    = ids.slice(start, end);
      const nextCursor  = end < ids.length ? b64Encode(end) : null;

      return { items: sliceIds, nextCursor } as const;
    },

    distinct: (field?: string) => {
      let next: EARS.EntityId[];
      if (!field) {
        next = [...new Set(ids)];
      } else {
        const seen = new Set<unknown>();
        next = ids.filter(id => {
          const val = getAttr(id, EARS.AttrKind.Custom(field));
          if (seen.has(val)) return false;
          seen.add(val);
          return true;
        });
      }
      return setIds(next);
    },

    groupBy: (field: string) => {
      const groups = new Map<unknown, EARS.EntityId[]>();
      ids.forEach(id => {
        const key = getAttr(id, EARS.AttrKind.Custom(field));
        const bucket = groups.get(key);
        if (bucket) {
          bucket.push(id);
        } else {
          groups.set(key, [id]);
        }
      });
      // Convert to qx instances only at the end
      const result = new Map<unknown, ReturnType<typeof qx>>();
      groups.forEach((ids, key) => result.set(key, qx(ids)));
      return result;
    },

    /*─ misc extractors ─*/
    ids: () => [...ids],
    id: () => self.first(),
    count: () => ids.length,
    first: () => ids[0] ?? null,
    last: () => (ids.length ? ids[ids.length - 1] : null),
    exists: () => ids.length > 0,

    /*─ functional helpers ─*/
    map: <T>(fn: (i: EARS.EntityId) => T) => ids.map(fn),
    forEach: (fn: (i: EARS.EntityId) => void) => (ids.forEach(fn), self),
    reduce: <T>(fn: (a: T, i: EARS.EntityId) => T, init: T) => ids.reduce(fn, init),
  } as const;

  return self;
};

```

# qx() Natural Language Examples

Simple examples for translating natural language to qx() query code.

### 1. Get all threads
```
prompt: "Get all threads"
code: return qx(EARS.Entity.Thread).pickAll();
```

### 2. Find thread by ID
```
prompt: "Get thread T-123"
code: return qx("T-123" as EARS.EntityId).pickOne();
```

### 3. Filter by status
```
prompt: "Find all open threads"
code: return qx(EARS.Entity.Thread)
        .where("status", "open")
        .pickAll();
```

### 4. Get documents in collection
```
prompt: "Get all documents in collection C-5"
code: return qx("C-5" as EARS.EntityId)
        .linksTo(EARS.RelKind.CONTAINS, EARS.Entity.Document)
        .pickAll();
```

### 5. Count entities
```
prompt: "Count total number of flows"
code: return qx(EARS.Entity.Flow).count();
```

### 6. Find by role
```
prompt: "Get the root flow"
code: return qx(EARS.Entity.Flow)
        .withRole("root_flow")
        .pickOne();
```

### 7. Sort by date
```
prompt: "Get threads sorted by most recent"
code: return qx(EARS.Entity.Thread)
        .orderBy("lastMessageTimestamp", "desc")
        .pickAll();
```

### 8. Get specific fields
```
prompt: "Get names and statuses of all threads"
code: return qx(EARS.Entity.Thread)
        .pick(["topic", "status"]);
```

### 9. Follow relationships
```
prompt: "Get all nodes in flow F-1"
code: return qx("F-1" as EARS.EntityId)
        .linksTo(EARS.RelKind.CONTAINS, EARS.Entity.Node)
        .pick(["label", "nodeType", "position"]);
```

### 10. Check existence
```
prompt: "Does document DOC-15 exist?"
code: return qx("DOC-15" as EARS.EntityId).first() !== null;
```

# tx() code
```
export interface SafeLinkOptions {
  /** Additional info to store with the relation */
  info?: unknown;
  /** If true, creates bidirectional edges automatically */
  symmetric?: boolean;
  /** If specified, prevents cycles within this group of relation kinds */
  acyclicGroup?: readonly EARS.RelKind[];
}

export function tx(typeOrId: EARS.Entity | EARS.EntityId, useProvidedId = false) {
  const isEntityType = Object.values(EARS.Entity).includes(typeOrId as EARS.Entity);

  // Generate new ID if entity type provided, otherwise use the provided ID
  const id: EARS.EntityId = isEntityType && !useProvidedId
    ? createEntity(typeOrId as EARS.Entity)
    : (typeOrId as EARS.EntityId);

  // Add timestamp for new entities (either from entity type or when explicitly marked as new)
  if (isEntityType || useProvidedId) {
    putAttr(id, EARS.AttrKind.Custom('createdAt'), Date.now());
  }

  const preventSelfLoop = (t: EARS.EntityId) => {
    if (t === id) throw new Error("tx.link(): source and target cannot be the same");
  };

  /*──────── core fluent surface ───────────*/
  const self = {
    /*─ attrs ─*/
    put: (k: EARS.AttrKind | string, v: unknown, allowMultiple = false) => {
      const kind = typeof k === "string" ? EARS.AttrKind.Custom(k) : k;
      if (allowMultiple) {
        addAttr(id, kind, v);
      } else {
        putAttr(id, kind, v);
      }
      return self;
    },
    add: (k: EARS.AttrKind | string, v: unknown) => {
      const kind = typeof k === "string" ? EARS.AttrKind.Custom(k) : k;
      addAttr(id, kind, v);
      return self;
    },
    batchPut: (attrs: Record<string, unknown>) => {
      for (const [k, v] of Object.entries(attrs)) {
        putAttr(id, EARS.AttrKind.Custom(k), v);
      }
      return self;
    },
    merge: (k: EARS.AttrKind, v: unknown, i?: number) => (mergeAttr(id, k, v, i), self),
    drop: (k: EARS.AttrKind, i?: number) => (dropAttr(id, k, i), self),
    dropIf: (k: EARS.AttrKind, c: unknown) => (dropIf(id, k, c), self),
    update: (k: EARS.AttrKind | string, v: unknown) => {
      const kind = typeof k === "string" ? EARS.AttrKind.Custom(k) : k;
      updateAttr(id, kind, v);
      return self;
    },
    updateBatch: (attrs: Record<string, unknown>) => {
      for (const [k, v] of Object.entries(attrs)) {
        updateAttr(id, EARS.AttrKind.Custom(k), v);
      }
      return self;
    },

    /*─ roles ─*/
    grant: (r: string) => {
      if (!getRoles(id).includes(r)) grantRole(id, r);
      return self;
    },
    revoke: (r: string) => {
      if (getRoles(id).includes(r)) revokeRole(id, r);
      return self;
    },
    ensure: (r: string, scope?: readonly EARS.EntityId[]) => {
      // Only query if scope not provided
      const entities = scope ?? qx().withRole(r).ids();
      entities.forEach(e => revokeRole(e, r));
      grantRole(id, r);
      return self;
    },

    /*─ relations (raw) ─*/
    link: (k: EARS.RelKind, t: EARS.EntityId, info?: unknown) => {
      preventSelfLoop(t); // ! this is being reached
      addRelation(id, k, t, info);
      return self;
    },
    relPatch: (
      rel: EARS.EntityId,
      u: { sourceEntity?: EARS.EntityId; targetEntity?: EARS.EntityId; info?: unknown },
    ) => {
      updateRelation(rel, u.sourceEntity, u.targetEntity, u.info);
      return self;
    },
    unlink: (rel: EARS.EntityId) => (removeRelation(rel), self),

    /*─ criteria‑edges (edge‑store) ─*/
    linkOne: (k: EARS.RelKind, t: EARS.EntityId, info?: unknown) => {
      preventSelfLoop(t);
      edgeStore.linkOne(id, k, t, info);
      return self;
    },
    safeLink: (k: EARS.RelKind, t: EARS.EntityId, options?: SafeLinkOptions) => {
      preventSelfLoop(t);

      const opts = options || {};

      // Check for cycles if configured
      if (opts.acyclicGroup && wouldCreateCycle(id, t, opts.acyclicGroup)) {
        // Generate meaningful error message based on context
        let errorMsg: string;
        if (opts.acyclicGroup.length === 1) {
          errorMsg = `Cannot create a ${k} relation that would form a cycle`;
        } else {
          const kinds = opts.acyclicGroup.join(', ');
          errorMsg = `Cannot create a ${k} relation that would form a cycle within [${kinds}]`;
        }
        throw new Error(errorMsg);
      }

      // Handle symmetric relations
      if (opts.symmetric) {
        linkSymmetric(id, t, k, opts.info);
        return self;
      }

      // Default behavior - regular linkOne
      return self.linkOne(k, t, opts.info);
    },
    patchLink: (
      k: EARS.RelKind,
      t: EARS.EntityId,
      u: { newTarget: EARS.EntityId; newInfo?: unknown },
    ) => {
      edgeStore.patchOne(
        { sourceEntity: id, relationType: k, targetEntity: t },
        { newTarget: u.newTarget, newInfo: u.newInfo },
      );
      return self;
    },
    unlinkIf: (k: EARS.RelKind, t?: EARS.EntityId) => (
      edgeStore.unlink({ sourceEntity: id, relationType: k, targetEntity: t }),
      self
    ),
    unlinkWhere: (c?: { kind?: EARS.RelKind; target?: EARS.EntityId }) => (
      edgeStore.unlink({
        sourceEntity: id,
        targetEntity: c?.target,
        relationType: c?.kind,
      }),
      self
    ),
    define: (def: {
      attributes?: Record<string, unknown>;
      links?: [EARS.RelKind, EARS.EntityId] | Array<[EARS.RelKind, EARS.EntityId]>;
      roles?: string | string[];
    }) => {
      if (def.attributes) {
        self.batchPut(def.attributes);
      }

      if (def.links) {
        const links = Array.isArray(def.links[0])
          ? def.links as Array<[EARS.RelKind, EARS.EntityId]>
          : [def.links] as Array<[EARS.RelKind, EARS.EntityId]>;

        for (const [kind, target] of links) {
          self.link(kind, target);
        }
      }

      if (def.roles) {
        const roles = Array.isArray(def.roles) ? def.roles : [def.roles];
        for (const role of roles) {
          self.grant(role);
        }
      }

      return self;
    },

    /*─ entity lifecycle ─*/
    destroy: (skipPersistence = false) => (destroyEntity(id, skipPersistence), undefined as never),

    /*─ misc ─*/
    id: () => id,
  } as const;

  return self;
};
```

# tx() Natural Language Examples

Simple examples for translating natural language to tx() code.

### 1. Create a new thread
```
prompt: "Create a new thread about user authentication"
code: return tx(EARS.Entity.Thread)
        .put("topic", "user authentication")
        .put("status", "open")
        .put("timestamp", Date.now())
        .id();
```

### 2. Update multiple fields
```
prompt: "Mark thread T-123 as resolved with a note"
code: return tx("T-123" as EARS.EntityId)
        .update("status", "resolved")
        .update("note", "Fixed in v2.1")
        .update("updatedAt", Date.now());
```

### 3. Create and link entities
```
prompt: "Create document 'API Guide' in collection C-5"
code: return (() => {
        const docId = tx(EARS.Entity.Document)
          .put("name", "API Guide")
          .id();
        tx("C-5" as EARS.EntityId).link(EARS.RelKind.CONTAINS, docId);
        return docId;
      })();
```

### 4. Update single field
```
prompt: "Change thread T-45 status to in-progress"
code: return tx("T-45" as EARS.EntityId).update("status", "in-progress");
```

### 5. Delete entity
```
prompt: "Delete document DOC-23"
code: return tx("DOC-23" as EARS.EntityId).destroy();
```

### 6. Link entities
```
prompt: "Link thread T-12 as parent of thread T-34"
code: return tx("T-12" as EARS.EntityId).link(EARS.RelKind.Custom("parent_of"), "T-34" as EARS.EntityId);
```

### 7. Set unique role
```
prompt: "Make flow F-1 the root flow"
code: return tx("F-1" as EARS.EntityId).ensure("root_flow");
```

### 8. Remove relationships
```
prompt: "Remove all parent links from thread T-22"
code: return tx("T-22" as EARS.EntityId).unlinkIf(EARS.RelKind.Custom("parent_of"));
```

### 9. Add multiple tags
```
prompt: "Add tags 'bug' and 'urgent' to thread T-99"
code: return tx("T-99" as EARS.EntityId)
        .add("tags", "bug")
        .add("tags", "urgent");
```

### 10. Create flow with nodes
```
prompt: "Create flow 'Onboarding' with entry and exit nodes"
code: return (() => {
        const flowId = tx(EARS.Entity.Flow)
          .put("label", "Onboarding")
          .put("status", "draft")
          .id();

        const entryId = tx(EARS.Entity.Node)
          .put("label", "Start")
          .put("nodeType", "entry")
          .id();

        const exitId = tx(EARS.Entity.Node)
          .put("label", "End")
          .put("nodeType", "exit")
          .id();

        tx(flowId).link(EARS.RelKind.CONTAINS, entryId);
        tx(flowId).link(EARS.RelKind.CONTAINS, exitId);
        tx(entryId).link(EARS.RelKind.TRANSITIONS_TO, exitId);

        return { flowId, entryId, exitId };
      })();
```

### 11. Delete all entities of a type
```
prompt: "Delete all settings entities"
code: return qx(EARS.Entity.Settings).ids().forEach(id => tx(id).destroy());
```
